mapper.select:
select id, house_id, batch_code, status, start_date, end_date, request_id, remark, create_by, create_time, update_by, update_time,
       (status != '已完成'
            and not exists (select 1 from batch_rabbits br
                            where br.batch_id = batches.id and br.is_active = 1)
       ) as pending_completion
from batches
where house_id = #{houseId}

    and batch_code like concat('%', #{q}, '%')

order by id desc
limit #{limit} offset #{offset}
